def split(blob): return [x.strip() for x in re.split(r"[;\n]", blob) if x.strip()]

SPORTS = [("flag football","flag football / 7v7"),("7 on 7","flag football / 7v7"),("7v7","flag football / 7v7"),("basketball","basketball"),("bball","basketball"),("football","football"),("soccer","soccer"),("baseball","baseball"),("softball","softball"),("slowpitch","softball"),("fastpitch","softball"),("volleyball","volleyball"),("hockey","hockey"),("lacrosse","lacrosse"),("wrestling","wrestling"),("singlet","wrestling"),("cheer","cheer"),("track","track"),("tennis","tennis"),("varsity","varsity jackets")]
def sport(k):
    for needle,name in SPORTS:
        if needle in k: return name
    return "all sports"
def page_type(k, forced=None):
    if forced: return forced
    if re.search(r"fundrais", k): return "fundraising guide"
    if "custom designed" in k: return "buyer's guide"
    if re.search(r"maker|creator|builder|designer|generator|mockup|template|customizer|design|create|make |make$|customize|make your|build your", k): return "design tool"
    if re.search(r"near me", k): return "local guide"
    return "buyer's guide"

rows=[]; seen={}
def add(blob, band, lst, forced=None):
    for k in split(blob):
        d=re.sub(r"[^a-z0-9]","",k.lower())+".com"
        if d in seen: print("DUP", k, "==", seen[d]); continue
        seen[d]=k; rows.append(dict(list=lst, band=band, keyword=k, domain=d, sport=sport(k), page=page_type(k, forced)))
add(A,"10K-100K","top200"); add(B,"1K-10K","top200"); add(TOOLS,"1K-10K","top200","tool / info page"); add(C_TOP,"100-1K","top200")
add(C_BENCH,"100-1K","bench"); add(C_TOOLS_BENCH,"100-1K","bench","tool / info page")

TM = re.compile(r"\\b(nike|adidas|under armou?r|champro|boombah|evoshield|rudis|triton|omni|rebel|healy|troy lee|kxk|fansidea|pro look|epic sports|stinger|spirit jersey|dri fit|nfl|nba|mlb|nhl|ncaa|aau|little league|pop warner|fifa|world cup|wooter|custom ink|fanatics|riddell|battle|gamebreaker|varsity cheer|varsity spirit|all star|rawlings|wilson|mizuno|russell|augusta|alleson)\\b")
