top=[r for r in rows if r["list"]=="top200"]; bench=[r for r in rows if r["list"]=="bench"]
print("top:",len(top),"bench:",len(bench),"total:",len(rows))
print("tm hits:",bad)
print("bad chars:",[r["domain"] for r in rows if not re.fullmatch(r"[a-z0-9]+\.com", r["domain"])])
print("max len:",max(len(r["domain"]) for r in rows), max(rows,key=lambda r:len(r["domain"]))["domain"])
print("top bands:",dict(collections.Counter(r["band"] for r in top)))
print("top page types:",dict(collections.Counter(r["page"] for r in top)))
print("top sports:",dict(collections.Counter(r["sport"] for r in top)))
print("bench page types:",dict(collections.Counter(r["page"] for r in bench)))
for i,r in enumerate(top,1): r["rank"]=i
